const $=selector=>document.querySelector(selector);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const deviceTheme=window.matchMedia('(prefers-color-scheme: dark)');
let chosenTheme=null;
// Service settings offers Light, Dark, and Match system. Match system forgets the manual choice.
function setTheme(theme,persist=true){
 if(theme==='system'){chosenTheme=null;try{localStorage.removeItem('lgcode-theme')}catch{}theme=deviceTheme.matches?'dark':'light';persist=false}
 if(!['light','dark'].includes(theme))return;
 document.documentElement.dataset.theme=theme;
 if(persist){chosenTheme=theme;try{localStorage.setItem('lgcode-theme',theme)}catch{}}
 document.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===(chosenTheme||'system'))));
}
function initializeTheme(){
 try{
  const saved=localStorage.getItem('lgcode-theme');
  if(['light','dark'].includes(saved))chosenTheme=saved;
  else{
   const legacy=localStorage.getItem('sheprd-mock-direction');
   if(legacy==='b'||legacy==='c'){chosenTheme=legacy==='b'?'light':'dark';localStorage.setItem('lgcode-theme',chosenTheme)}
  }
 }catch{}
 setTheme(chosenTheme||(deviceTheme.matches?'dark':'light'),false);
}
deviceTheme.addEventListener('change',event=>{if(chosenTheme===null)setTheme(event.matches?'dark':'light',false)});




