function updateSettingsNav(){const body=$('#view-body'),top=body.getBoundingClientRect().top+32;let current=settingsSections[0][0];for(const [id] of settingsSections){const el=$('#settings-'+id);if(el&&el.getBoundingClientRect().top<=top)current=id}if(body.scrollTop>0&&body.scrollTop+body.clientHeight>=body.scrollHeight-2)current=settingsSections.at(-1)[0];document.querySelectorAll('[data-settings-nav]').forEach(b=>b.toggleAttribute('aria-current',b.dataset.settingsNav===current))}
