function pairDiffRows(rows){const pairs=[];let removed=[],added=[];const flush=()=>{for(let i=0;i<Math.max(removed.length,added.length);i++)pairs.push({left:removed[i]||null,right:added[i]||null});removed=[];added=[]};for(const r of rows){if(r.kind==='removed')removed.push(r);else if(r.kind==='added')added.push(r);else{flush();pairs.push(r.kind==='hunk'?{hunk:r}:{left:r,right:r})}}flush();return pairs}
const splitCell=(r,key)=>r?`<pre class="diff-line ${r.kind}"><span>${r[key]}</span>${esc(r.text)}</pre>`:'<pre class="diff-line filler" aria-hidden="true"> </pre>';
// As Visual Studio Code does, a split diff needs 900 pixels; below that it reads as unified.
// GIT-2: below 1600 pixels the worktree list starts as a 40 pixel rail. The owner's choice is remembered. Phones keep the strip of worktrees.
const narrowGit=matchMedia('(max-width:1599px)'),gitColumns=matchMedia('(min-width:901px)');let worktreeFold=null;try{const v=localStorage.getItem('lgcode-git-worktrees');if(v)worktreeFold=v==='rail'}catch{}
const worktreeRail=()=>gitColumns.matches&&(worktreeFold??narrowGit.matches);
narrowGit.addEventListener('change',()=>{if(state.view==='source-control'&&worktreeFold===null){remember();render()}});
const gitChangesWidth=()=>parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--git-changes-width'))||280;
const gitPaneWidth=()=>$('#view-body').clientWidth-gitChangesWidth(),splitFits=()=>gitPaneWidth()>=900,worktreesFit=()=>gitPaneWidth()-(worktreeRail()?40:240)>=900;
function diffBody(path,mode=diffMode){const rows=numberDiff(diffRows(path));if(mode==='split'&&splitFits())return `<div class="split-diff"><h3>Before</h3><h3>After</h3>${pairDiffRows(rows).map(x=>x.hunk?`<pre class="diff-line hunk">${esc(x.hunk.text)}</pre>`:splitCell(x.left,'before')+splitCell(x.right,'after')).join('')}</div>`;return `<div class="unified-diff">${rows.map(r=>r.kind==='hunk'?`<pre class="diff-line hunk">${esc(r.text)}</pre>`:`<pre class="diff-line ${r.kind}"><span class="line-old">${r.before}</span><span class="line-new">${r.after}</span><span class="line-one" aria-hidden="true">${r.after||r.before}</span><b>${r.kind==='added'?'+':r.kind==='removed'?'−':' '}</b>${esc(r.text)}</pre>`).join('')}</div>`}
const diffCounts=path=>{const rows=diffRows(path);return `<span class="added">+${rows.filter(r=>r[0]==='added').length}</span> <span class="removed-count">−${rows.filter(r=>r[0]==='removed').length}</span>`};
let diffScope='file';
const sourceCommits=()=>api.git.log(workspace().id);
function diffPane(w,commit,files,path){const g=gitState(w),open=f=>!commit&&g.conflicts.has(f);if(path&&open(path))return conflictPane(w,path);
 return `<div class="diff-content">${path?`<header class="diff-toolbar"><code id="diff-path">${diffScope==='all'&&files.length>1?files.length+' files':esc(path)}</code><div class="diff-toolbar-controls"><div class="segmented" aria-label="Files shown"><button data-diff-scope="file" aria-pressed="${diffScope!=='all'}">This file</button><button data-diff-scope="all" aria-pressed="${diffScope==='all'}">All files</button></div><div class="segmented" aria-label="Diff layout"><button data-diff-mode="unified" aria-pressed="${diffMode==='unified'}">Unified</button><button data-diff-mode="split" aria-pressed="${diffMode==='split'}">Split</button></div></div></header>${diffMode==='split'&&!splitFits()?'<p class="op-caption" id="split-note">Split needs a wider window, so this diff is unified.</p>':diffMode==='split'&&!worktreesFit()?'<p class="op-caption" id="split-note">Split hides the worktree list. Choose Unified to bring it back.</p>':''}<p id="diff-context" class="op-caption">${commit?'Commit '+esc(commit.id):'Uncommitted changes'} · ${esc(w.branch)} · ${esc(machineFor().name)}</p>${diffScope==='all'?files.map(f=>`<section class="diff-file"><header class="diff-file-header"><code>${esc(f)}</code><small>${open(f)?'<span class="conflict-mark">Conflict</span>':diffCounts(f)}</small></header>${open(f)?`<p class="conflict-note">This file has a conflict. <button class="inline-link" data-source-file="${esc(f)}">Resolve it here</button></p>`:diffBody(f)}</section>`).join(''):diffBody(path)}`:emptyState(`No uncommitted changes on <code>${esc(w.branch)}</code>.`)}</div>`}
// CONFLICT-1: a conflict opens in the diff pane. Each conflict shows ours, the base, and theirs, and keeps ours, theirs, or both. Mark resolved needs a choice for every conflict.
function conflictPane(w,path){const c=api.git.conflict(w.id,path),can=gitCanWrite(w),hunks=c.segments.filter(x=>!x.context).length,chosen=c.choices.filter(Boolean).length;let n=0;
 const rows=list=>list.length?list.map(t=>`<pre class="diff-line">${esc(t)}</pre>`).join(''):'<p class="conflict-empty">No lines</p>';
 const body=c.segments.map(x=>{if(x.context)return x.context.map((t,i)=>`<pre class="diff-line context"><span>${x.line+i}</span>${esc(t)}</pre>`).join('');const i=n++,choice=c.choices[i],result=choice==='ours'?x.ours:choice==='theirs'?x.theirs:choice==='both'?[...x.ours,...x.theirs]:null;
  return `<section class="conflict-hunk${choice?' is-chosen':''}" aria-label="Conflict ${i+1} of ${hunks}"><header class="conflict-head"><strong>Conflict ${i+1} of ${hunks}</strong><div class="segmented" role="group" aria-label="Keep for conflict ${i+1}">${[['ours','Ours'],['theirs','Theirs'],['both','Both']].map(([v,label])=>`<button data-hunk-choice="${v}" data-hunk="${i}" data-conflict-path="${esc(path)}" aria-pressed="${choice===v}" ${can?'':'disabled'}>${label}</button>`).join('')}</div></header>${result?`<div class="conflict-side result"><p class="conflict-label">Result · ${choice==='both'?'ours, then theirs':choice}</p>${rows(result)}</div>`:`<div class="conflict-side ours"><p class="conflict-label">Ours · <code>${esc(c.ours)}</code></p>${rows(x.ours)}</div><div class="conflict-side base"><p class="conflict-label">Base</p>${rows(x.base)}</div><div class="conflict-side theirs"><p class="conflict-label">Theirs · <code>${esc(c.theirs)}</code></p>${rows(x.theirs)}</div>`}</section>`}).join('');
 const reason=!canOperate()?'Resolving waits for the connection.':!can?'This worktree\'s machine is offline.':chosen<hunks?(hunks-chosen===1?'Choose ours, theirs, or both for the last conflict.':`Choose ours, theirs, or both for ${hunks-chosen} conflicts.`):'';
 return `<div class="diff-content conflict-pane"><header class="diff-toolbar"><code id="diff-path">${esc(path)}</code><div class="diff-toolbar-controls"><button class="secondary dense" data-open-in-terminal="${esc(path)}" ${canOperate()?'':'disabled'}>${icon('terminal')}Open in Terminal</button></div></header><p id="diff-context" class="op-caption">${plural(hunks,'conflict')} between ours, <code>${esc(c.ours)}</code>, and theirs, <code>${esc(c.theirs)}</code>. The base is the version both changed.</p><div class="conflict-file">${body}</div><footer class="conflict-actions"><button class="primary" id="mark-resolved" data-conflict-path="${esc(path)}" aria-describedby="conflict-reason" ${reason?'disabled':''}>Mark resolved</button><p class="disabled-reason" id="conflict-reason">${esc(reason)}</p></footer></div>`}
// PSET-1: Project settings lists the facts as labels and values, links the machine to its placement, and saves the shell as it changes. Rename and Archive sit at the top right, and Archive asks first.
function workspaceSettingsView(){const project=p(),w=projectWorkspace(),prefs=workspacePreferences.get(project.id)||{shell:'default'},m=machineFor(),next=machineItems.find(x=>x.id===futureProjectMachines.get(project.id)),live=canOperate();return `<div class="page-top">${project.archivedAt?`<p class="archived-note">${icon('archive')}Archived ${stampTime(project.archivedAt)}. The sidebar and Home leave it out, and All projects still lists it.</p>`:''}<div class="page-actions"><button class="secondary" id="rename-project" ${live?'':'disabled'}>${icon('pencil')}Rename</button>${project.archivedAt?`<button class="primary" id="restore-project" ${live?'':'disabled'}>${icon('archive-restore')}Restore</button>`:`<button class="secondary" id="archive-project" ${live?'':'disabled'}>${icon('archive')}Archive</button>`}</div></div><section class="settings-section" aria-labelledby="workspace-location-title"><h2 id="workspace-location-title">Where this project runs</h2><dl id="workspace-location" class="workspace-location fact-list"><dt>Repository</dt><dd>${esc(repo().name)}</dd><dt>Branch</dt><dd><code>${esc(w.branch)}</code></dd><dt>Checkout</dt><dd>${w.path===repositoryLocations.get(w.repoId+'/'+w.machineId)?'Main checkout':'Project worktree'}</dd><dt>Folder</dt><dd><code>${esc(w.path)}</code></dd><dt>Machine</dt><dd>${esc(m.name)}${next&&next.id!==m.id?` <span class="muted">· next run on ${esc(next.name)}</span>`:''} <button class="inline-link" data-open-placement="${project.id}">Change placement</button></dd></dl></section><section class="settings-section" aria-labelledby="workspace-terminal-title"><h2 id="workspace-terminal-title">Terminal</h2>${fieldLabel('workspace-shell','Preferred shell')}<select id="workspace-shell" ${live?'':'disabled'}>${[['default','Machine default'],['bash','Bash'],['zsh','Zsh']].map(([v,label])=>`<option value="${v}" ${prefs.shell===v?'selected':''}>${label}</option>`).join('')}</select><p class="op-caption">Used for new terminal sessions in this worktree.</p></section>`}
// MACH-2: an overloaded machine says so in amber, an offline one says when it was last seen, and each row's menu renames or removes it. On a phone each row is a two-line list.
const machineAgents=m=>projects.filter(project=>machineFor(project).id===m.id).flatMap(agents).filter(a=>runtimeFor(a.id).state==='running').length;
function machineSlots(m){const used=machineAgents(m);return used>m.slots?`<span class="over-limit" title="${used} running agents on ${m.slots} slots">${icon('triangle-alert')}${used} of ${m.slots}<span class="stack-only"> slots</span> · Over limit</span>`:`${used} of ${m.slots}<span class="stack-only"> slots</span>`}
const machineStatus=m=>`<span class="dot ${m.status==='Online'?'':m.status==='Offline'?'idle':'wait'}"></span> ${esc(m.status)}${m.status==='Offline'&&m.lastSeenAt?`<span class="muted"> · Last seen ${agoText(H.clock-m.lastSeenAt)}</span>`:''}`;
// WORKER-1: once paired, a worker shows its master, the connection, and Disconnect instead of the pairing form.
const joinMasterForm=()=>`<form class="settings-section" id="join-master-form"><h2>Join a master</h2><p class="op-caption">On the master, Connect machine shows its address and a pairing code.</p><label for="master-address">Master address</label><input id="master-address" type="url" placeholder="https://studio.example" required><label for="master-code">Pairing code</label><input id="master-code" autocomplete="off" placeholder="Enter pairing code" required><div class="form-actions"><button class="secondary" id="join-master">Pair with master</button></div></form>`;
const workerStatus=()=>`<section class="settings-section worker-status" aria-labelledby="worker-status-title"><h2 id="worker-status-title">Master</h2><dl class="fact-list"><dt>Master</dt><dd><code>${esc(H.master.address)}</code></dd><dt>Connection</dt><dd id="machine-mode-state"><span class="dot ${canOperate()?'':'wait'}"></span> ${canOperate()?'Connected since '+stampTime(H.master.since):'Waiting for the connection'}</dd></dl><p class="op-caption">The master sends this computer its work.</p><div class="form-actions"><button class="secondary" id="leave-master" ${canOperate()?'':'disabled'}>Disconnect</button></div></section>`;
function machinesView(){const master=machineMode==='master',role=`<p class="machine-role"><span>This computer</span><strong id="machine-role">${master?'Master':'Worker'}</strong><button class="secondary dense" id="change-role">Change role</button></p>`;if(!master)return `<section class="machine-page"><div class="page-top">${role}</div>${H.master.address?workerStatus():joinMasterForm()}</section>`;return `<section class="machine-page"><div class="page-top">${role}<div class="page-actions"><button class="secondary" id="connect-machine">Connect machine</button></div></div><div class="compact-table-wrap"><table class="compact-table machine-table stack-table" aria-label="Machines"><thead><tr><th>Machine</th><th>Status</th><th>Role</th><th>Agent slots</th><th>Projects</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${machineItems.map(m=>{const count=projects.filter(project=>machineFor(project).id===m.id).length;return `<tr data-machine-row="${m.id}"><td class="machine-name">${esc(m.name)}</td><td class="stack-status">${machineStatus(m)}</td><td>${esc(m.role)}</td><td>${machineSlots(m)}</td><td>${count}<span class="stack-only"> ${count===1?'project':'projects'}</span></td><td class="row-end">${m.status==='Awaiting confirmation'?`<button class="secondary dense" data-confirm-machine="${m.id}">Confirm pairing</button>`:m.status==='Online'?`<button class="secondary dense" data-new-on-machine="${m.id}">New project here</button>`:''}${rowMenuButton('machine',m.id,m.name)}</td></tr>`}).join('')}</tbody></table></div><section class="fleet-placement" aria-labelledby="placement-title"><h2 id="placement-title">Project placement</h2><p id="placement-message" class="op-caption" role="status">${esc(placementNotice)}</p><div class="compact-table-wrap"><table class="compact-table placement-table stack-table" aria-labelledby="placement-title"><thead><tr><th>Project</th><th>Repository</th><th>Branch</th><th>Next run on</th></tr></thead><tbody>${projects.map(project=>`<tr><td>${esc(project.name)}</td><td>${esc(repoFor(project).name)}</td><td><code>${esc(projectWorkspace(project).branch)}</code></td><td class="row-end"><select data-project-machine="${project.id}" aria-label="Machine for ${esc(project.name)}">${machineItems.map(m=>`<option value="${m.id}" ${(futureProjectMachines.get(project.id)||machineFor(project).id)===m.id?'selected':''} ${m.status==='Online'&&repositoryLocations.has(project.repoId+'/'+m.id)?'':'disabled'}>${esc(m.name)}${m.status==='Online'?'':' · '+m.status}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div></section></section>`}
function openSignIn(sub){const machine=machineItems.find(m=>m.id===sub.machineId),online=machine.status==='Online';signingSubscription=sub.id;$('#subscription-login-title').textContent=`Sign in to ${harnessLabels[sub.harness]} on ${machine.name}`;$('#subscription-login-context').textContent=`Subscription ${sub.name}. This login stays private to this subscription.`;$('#sign-in-close').textContent='Cancel';if(!online){$('#sign-in-output').textContent='';$('#sign-in-status').textContent=`${machine.name} is ${machine.status.toLowerCase()}, so its terminal cannot open.`;$('#subscription-login').showModal();return}$('#sign-in-output').textContent='';$('#sign-in-status').textContent='Waiting for sign-in.';$('#subscription-login').showModal();api.accounts.signIn(sub.id).then(login=>{$('#sign-in-output').textContent=`$ ${login.command}\nOpen ${login.url}\nand enter the code ${login.code}`})}
