 if(b.id==='change-role'){const toWorker=machineMode==='master',workers=machineItems.filter(m=>m.role==='Worker').length,count=projects.length;$('#role-title').textContent=toWorker?'Make this computer a worker?':'Make this computer the master?';$('#role-impact').textContent=toWorker?`${workers} ${workers===1?'worker':'workers'} and ${count} ${count===1?'project':'projects'} depend on ${thisMachine.name}. They receive no new work until a master takes over, and this computer must pair with a master.`:H.master.address?`This computer stops taking work from ${H.master.address}, and it starts coordinating its own projects.`:'This computer starts coordinating projects, and other computers can pair with it.';$('#confirm-role').textContent=toWorker?'Make worker':'Make master';$('#role-dialog').showModal();return}
 if(b.id==='confirm-role'){machineMode=machineMode==='master'?'worker':'master';if(machineMode==='master')api.machines.leave();api.machines.setRole(thisMachine.id,machineMode==='master'?'Master':'Worker');$('#role-dialog').close();render();return}
