// GIT-2: one set of resize rules serves the sidebar, the thread panel, and Git's commit pane.
const resizeKinds={sidebar:{min:224,max:()=>360,start:248,end:360,prop:'--sidebar-width',handle:'#sidebar-resize',pane:'#sidebar',dir:1},lead:{min:320,max:()=>Math.max(320,Math.min(600,innerWidth-650)),start:360,end:540,prop:'--lead-width',handle:'#lead-resize',pane:'#lead-panel',dir:-1},git:{min:240,max:()=>Math.max(240,Math.min(480,($('#view-body')?.clientWidth||1200)-(worktreeRail()?40:240)-360)),start:280,end:480,prop:'--git-changes-width',handle:'#git-resize',pane:'.git-changes',dir:1,after:()=>{if(diffMode!=='split')return;const now=[splitFits(),worktreesFit()].join();if(now!==splitLayout){splitLayout=now;remember();render();$('#git-resize')?.focus()}}}};
