const clockTime=ms=>new Date(ms).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:H.timeZone});
const formatWait=ms=>{const minutes=Math.floor(ms/60000);if(minutes<1)return 'Just now';if(minutes<60)return minutes+' min';if(minutes<1440){const left=minutes%60;return Math.floor(minutes/60)+' hr'+(left?' '+left+' min':'')}const days=Math.floor(minutes/1440);return days+(days===1?' day':' days')};
function homeFact(item){const since=attentionSince(item),blocks=item.request?.taskId||(item.merge?null:item.project.tasks.find(t=>t.owner===item.agentId&&['active','review'].includes(t.state))?.id);return {waited:since==null?null:formatWait(H.clock-since),blocks}}
