 ...permissionItems.map(r=>({key:'approval:'+r.id,kind:'Approval',project:projects.find(p=>p.id===r.projectId),agentId:r.agentId,title:r.title,status:r.status==='open'?'open':r.status==='cancelled'?'cancelled':'answered',permission:r})),
 ...projects.flatMap(project=>agents(project).filter(a=>runtimeFor(a.id).failure).map(a=>({key:'failure:'+a.id,kind:'Failed start',project,agentId:a.id,title:failureLabel(a.id),status:'open'})))
