function homeSourceLink(item){return item.merge?`data-inspect-merge="${esc(item.merge.id)}"`:item.request?`data-open-request="${esc(item.request.id)}"`:item.permission?`data-open-permission="${esc(item.permission.id)}"`:`data-alert-agent="${esc(item.agentId)}"`}
