// The phone, from the designer's critique of 2026-11-06: TOP-3, PHONE-1, PHONE-2, and PHONE-3.
// TOP-3: a phone's top bar holds the menu, the place, and the bell. The connection is a dot on the bell, and the bell opens its full state with Reconnect now. The branch moves into the tab content, on a line under the tabs.
function placePhoneControls(){const phone=mobile.matches,ctx=$('#context-toggle'),put=(parent,...els)=>{for(const el of els)if(el.parentElement!==parent)parent.append(el)};
 if(phone){put($('#menu-connection'),$('#connection-status'),$('#retry-connection'));put($('#phone-context'),ctx)}else put($('.topbar'),$('#connection-status'),$('#retry-connection'),ctx);
 $('#menu-connection').hidden=!phone;$('#phone-context').hidden=!phone||ctx.hidden||ctx.parentElement!==$('#phone-context')}
const previousConnection=renderConnection;
renderConnection=function(){previousConnection();const c=sampleConnection;$('#bell-dot').className='bell-dot dot '+(c==='Live'?'':c==='Offline'?'error':'wait');if(mobile.matches){const label=$('#attention-toggle').getAttribute('aria-label')||'';$('#attention-toggle').setAttribute('aria-label',label.replace(/\. LGcode is .*$/,'')+'. LGcode is '+c.toLowerCase())}};
$('#context-menu').addEventListener('beforetoggle',e=>{const menu=$('#context-menu');if(e.newState!=='open')return;if(!mobile.matches){menu.style.top='';return}const r=$('#context-toggle').getBoundingClientRect();menu.style.top=Math.min(r.bottom+4,innerHeight-160)+'px'});
// PHONE-2: on a phone the drawer is the tree. Agents needing attention come first, and the service pages follow the tree at the end of the one scroll.
function drawerAttention(){const seen=new Map();for(const item of attentionQueue()){const project=item.project,a=findAgent(item.agentId,project);if(a&&!seen.has(a.id))seen.set(a.id,{a,project})}return [...seen.values()]}
const previousPhoneSidebar=renderSidebar;
renderSidebar=function(){previousPhoneSidebar();const box=$('#drawer-attention'),rows=mobile.matches?drawerAttention():[];box.hidden=!rows.length;box.innerHTML=rows.length?`<h2 id="drawer-attention-title">Needs attention<small>${rows.length}</small></h2>${rows.map(({a,project})=>{const st=agentStatus(a,project);return `<button class="drawer-agent ${st.failed?'failed':''}" data-drawer-agent="${a.id}" data-project-ref="${project.id}"><span class="dot ${st.dot}"></span><span class="agent-name">${esc(a.name)}</span><small>${esc(st.text)} · ${esc(project.name)}</small></button>`}).join('')}`:''};
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-drawer-agent]');if(b)openAgent(b.dataset.drawerAgent,b.dataset.projectRef)});
// PHONE-3: on a phone the board is one list. Sprints that need the owner come first, then the rest by status, and each card starts with its status.
