boardView=function(){const project=p();if(!mobile.matches||!project.sprints.length)return previousPhoneBoard();const list=[...project.sprints].sort((a,b)=>Boolean(sprintAttention(b,project))-Boolean(sprintAttention(a,project))||phoneBoardOrder[sprintState(a)]-phoneBoardOrder[sprintState(b)]);return stageStrip()+`<ol class="board-list" aria-label="Sprints, those needing you first">${list.map(s=>`<li>${sprintCard(s).replace('<span class="sprint-id">',`<span class="sprint-id"><span class="sprint-list-state">${sprintStatusNames[sprintState(s)]}</span> · `)}</li>`).join('')}</ol>`};
// Only the board and the drawer change with the phone layout, so a resize does not redraw a form the owner is typing in.
